cd /workspace/submission && cat > netnomos/finite.py <<'PYEOF'
"""Finite telemetry adapter for AST projection, evidence mining and decoding.

The module adapts the JSON job of the telemetry rule compiler protocol to the
NetNomos AST, compiles every predicate into a vectorised evaluator and then runs
the exact finite pipeline:

1. mixed-radix enumeration of the declared Cartesian window universe,
2. exhaustive discovery of every inclusion-minimal clause of length at most
   ``width`` that holds on all training windows and is falsified somewhere in
   the universe, together with its deterministic witnesses/counterexample,
3. restriction of the theory to the operator-approved discovered clauses,
4. exact decoding of every query over the joint approved theory.
"""
from __future__ import annotations

import itertools
from typing import Any, Callable

import numpy as np

from netnomos.ast import (
    BinaryTerm,
    BoolConst,
    BoolNot,
    Compare,
    Constant,
    FuncCall,
    Formula,
    SymbolRef,
    formula_to_string,
)
from netnomos.learners.hittingset import enumerate_minimal_clauses
from netnomos.projection import (
    GroundedPredicate,
    SelectedConstant,
    project_quantified_family,
)
from netnomos.specs import (
    Comparator,
    ConstantSelectorSpec,
    DatasetSpec,
    FieldRole,
    FieldSpec,
    QuantifierTemplateSpec,
    SourceSpec,
    SourceType,
    ValueType,
    VariableSelectorSpec,
)
from netnomos.theory import compile_formula

OPS = dict(eq="=", ne="!=", lt="<", le="<=", gt=">", ge=">=")
DIGITS = "0123456789"


def _lowest_set_bit(value: int) -> int:
    """Index of the lowest set bit of a positive Python int."""
    return (value & -value).bit_length() - 1


def _mask_of(flags: np.ndarray) -> int:
    """Pack a boolean window flag array into a little-endian bit mask int."""
    if flags.size == 0:
        return 0
    return int.from_bytes(np.packbits(flags, bitorder="little").tobytes(), "little")


class WindowSchema:
    """Field/column layout of one job plus its AST predicate definitions."""

    def __init__(self, job: dict[str, Any]):
        self.job = job
        self.order: list[str] = [field["name"] for field in job["fields"]]
        self.names: dict[str, int] = {name: index for index, name in enumerate(self.order)}
        self.types: dict[str, str] = {field["name"]: field["type"] for field in job["fields"]}
        self.field_domains: list[list[int]] = [list(field["domain"]) for field in job["fields"]]
        self.slots: int = int(job["slots"])
        self.nf: int = len(self.order)
        self.domains: list[list[int]] = [
            list(field["domain"]) for _ in range(self.slots) for field in job["fields"]
        ]
        self.columns: list[str] = [f"cell_{index}" for index in range(len(self.domains))]
        self.positions: dict[str, int] = {name: index for index, name in enumerate(self.columns)}
        self.families: dict[str, list[str]] = {
            field["name"]: [
                self.columns[self.position([slot, field["name"]])] for slot in range(self.slots)
            ]
            for field in job["fields"]
        }
        self.fields: dict[str, FieldSpec] = {
            self.columns[slot * self.nf + index]: FieldSpec(
                name=self.columns[slot * self.nf + index],
                value_type=ValueType.INTEGER,
                roles=[FieldRole(field["type"]) if field["type"] != "id" else FieldRole.IDENTIFIER],
                domain=list(field["domain"]),
                context_family=field["name"],
                context_index=slot,
            )
            for slot in range(self.slots)
            for index, field in enumerate(job["fields"])
        }
        self.spec = DatasetSpec(
            name="finite-windows",
            source=SourceSpec(type=SourceType.CSV),
            fields=list(self.fields.values()),
        )

    def position(self, ref: list[Any]) -> int:
        """Flattened cell index of a ``[slot, field_name]`` reference."""
        return ref[0] * self.nf + self.names[ref[1]]

    def term(self, term: dict[str, Any]) -> Any:
        """Translate a protocol term into the NetNomos term AST."""
        if "const" in term:
            return Constant(term["const"])
        if "sum" in term:
            return FuncCall("sum", tuple(SymbolRef(self.columns[self.position(ref)]) for ref in term["sum"]))
        ref = SymbolRef(self.columns[self.position(term["ref"])])
        return BinaryTerm("*", Constant(term["scale"]), ref) if "scale" in term else ref

    def predicates(self) -> list[GroundedPredicate]:
        """Grounded AST form of every input predicate, keeping input ids."""
        result: list[GroundedPredicate] = []
        for index, predicate in enumerate(self.job["predicates"]):
            op = Comparator(OPS[predicate["op"]])
            if predicate["kind"] == "cmp":
                formula: Formula = Compare(op.value, self.term(predicate["left"]), self.term(predicate["right"]))
                display = formula_to_string(formula)
            else:
                template = QuantifierTemplateSpec(
                    name="window",
                    quantifier="exists" if predicate["kind"] == "any" else "forall",
                    selector=VariableSelectorSpec(),
                    operators=[op],
                    constant=ConstantSelectorSpec(mode="explicit", values=[predicate["value"]]),
                )
                formula, display = project_quantified_family(
                    predicate["field"],
                    self.families[predicate["field"]],
                    template,
                    op,
                    SelectedConstant(predicate["value"], None),
                )
            result.append(
                GroundedPredicate(
                    str(index),
                    formula,
                    display,
                    0.0,
                    {"position": index, "kind": predicate["kind"]},
                )
            )
        return result


class WindowUniverse:
    """Every window over the declared domains in mixed-radix protocol order.

    Index 0 is the all-smallest window; the last cell (highest slot, last field)
    varies fastest.  Domain positions, not numeric gaps, are the digits.
    """

    def __init__(self, schema: WindowSchema):
        self.schema = schema
        self.cells = schema.slots * schema.nf
        self.cell_field = [
            field_index for _ in range(schema.slots) for field_index in range(schema.nf)
        ]
        self.radices = [len(schema.field_domains[field_index]) for field_index in self.cell_field]
        size = 1
        for radix in self.radices:
            size *= radix
        self.size = int(size)
        self.multipliers = [0] * self.cells
        weight = 1
        for cell in range(self.cells - 1, -1, -1):
            self.multipliers[cell] = weight
            weight *= self.radices[cell]
        self.domain_arrays = [
            np.asarray(domain, dtype=np.int64) for domain in schema.field_domains
        ]
        self.matrix = self._enumerate()

    def _enumerate(self) -> np.ndarray:
        positions = np.arange(self.size, dtype=np.int64)
        matrix = np.empty((self.size, self.cells), dtype=np.int64)
        for cell in range(self.cells):
            values = self.domain_arrays[self.cell_field[cell]]
            matrix[:, cell] = values[(positions // self.multipliers[cell]) % self.radices[cell]]
        return matrix

    def train_matrix(self, train: list[list[list[int]]]) -> np.ndarray:
        rows = [list(itertools.chain.from_iterable(window)) for window in train]
        if not rows:
            return np.zeros((0, self.cells), dtype=np.int64)
        matrix = np.asarray(rows, dtype=np.int64)
        return matrix.reshape(len(rows), self.cells)

    def index_of(self, window: list[list[int]]) -> int:
        """Universe index of one concrete window (used by diagnostics/tests)."""
        flat = list(itertools.chain.from_iterable(window))
        index = 0
        for cell, value in enumerate(flat):
            domain = self.schema.field_domains[self.cell_field[cell]]
            index += domain.index(value) * self.multipliers[cell]
        return index

    def column(self, ref: list[Any]) -> np.ndarray:
        return self.matrix[:, self.schema.position(ref)]


def _spelling_exists(values: np.ndarray, prefix: str) -> bool:
    """Does any sorted value have a canonical decimal spelling with this prefix?"""
    if values.size == 0:
        return False
    if not prefix:
        return True
    if prefix[0] == "0":
        # Canonical spellings never carry leading zeros, so "0" is the only
        # spelling that starts with "0".
        return prefix == "0" and bool((values == 0).any())
    length = len(prefix)
    base = int(prefix)
    for digit_count in range(length, 8):
        step = 10 ** (digit_count - length)
        low = base * step
        high = low + step - 1
        if digit_count >= 2 and low < 10 ** (digit_count - 1):
            low = 10 ** (digit_count - 1)
        if low > high:
            continue
        if high > 10 ** digit_count - 1:
            high = 10 ** digit_count - 1
        position = int(np.searchsorted(values, low, side="left"))
        if position < values.size and int(values[position]) <= high:
            return True
    return False


def _spelling_equals(values: np.ndarray, prefix: str) -> bool:
    """Is ``prefix`` exactly the canonical spelling of one of ``values``?"""
    if not prefix:
        return False
    value = int(prefix)
    if str(value) != prefix:
        return False
    return bool((values == value).any())


def prefix_tokens(values: np.ndarray, prefix: str) -> list[str]:
    """Next tokens, in protocol order ``"0".."9"`` then ``"END"``."""
    tokens = [digit for digit in DIGITS if _spelling_exists(values, prefix + digit)]
    if _spelling_equals(values, prefix):
        tokens.append("END")
    return tokens


class ClauseMiner:
    """Discovery of every protocol-eligible clause with its certificates."""

    def __init__(self, schema: WindowSchema, universe: WindowUniverse, width: int):
        self.schema = schema
        self.universe = universe
        self.width = int(width)
        self.predicates = schema.predicates()
        self.evaluators: list[Callable[[np.ndarray], np.ndarray]] = [
            compile_formula(predicate.formula, schema.positions) for predicate in self.predicates
        ]
        self.train_matrix = universe.train_matrix(schema.job["train"])
        self.train_masks: list[int] = []
        self.universe_flags: list[np.ndarray] = []
        self.universe_masks: list[int] = []
        self._evaluate()

    def _evaluate(self) -> None:
        train_total = self.train_matrix.shape[0]
        for predicate, evaluator in zip(self.predicates, self.evaluators):
            train_flags = evaluator(self.train_matrix)
            universe_flags = evaluator(self.universe.matrix)
            predicate.support = float(train_flags.mean()) if train_total else 0.0
            self.train_masks.append(_mask_of(train_flags))
            self.universe_flags.append(universe_flags)
            self.universe_masks.append(_mask_of(universe_flags))
        self.full_train = (1 << train_total) - 1
        self.full_universe = (1 << self.universe.size) - 1

    def rules(self) -> list[dict[str, Any]]:
        """Every eligible clause as ``{"clause", "witnesses", "counterexample"}``."""
        found = enumerate_minimal_clauses(
            self.train_masks,
            self.universe_masks,
            self.width,
            self.train_matrix.shape[0],
            self.universe.size,
        )
        found.sort(key=lambda item: (len(item[0]), item[0]))
        rules: list[dict[str, Any]] = []
        for clause, truth in found:
            covered = 0
            for literal in clause:
                covered |= self.train_masks[literal]
            witnesses = [
                _lowest_set_bit(self.train_masks[literal] & ~covered) for literal in clause
            ]
            rules.append(
                {
                    "clause": list(clause),
                    "witnesses": witnesses,
                    "counterexample": _lowest_set_bit(truth ^ self.full_universe),
                }
            )
        return rules


def active_theory(rules: list[dict[str, Any]], approved: list[list[int]]) -> list[list[int]]:
    """Approved clauses that were actually learned, in rule order."""
    selected = {tuple(clause) for clause in approved}
    return [rule["clause"] for rule in rules if tuple(rule["clause"]) in selected]


def decode_queries(
    schema: WindowSchema,
    universe: WindowUniverse,
    universe_flags: list[np.ndarray],
    active: list[list[int]],
    queries: list[dict[str, Any]],
) -> list[dict[str, Any]]:
    """Exact joint-theory decoding of every query, in input order."""
    active_flags: list[np.ndarray] = []
    for clause in active:
        flags = universe_flags[clause[0]].copy()
        for literal in clause[1:]:
            flags |= universe_flags[literal]
        active_flags.append(flags)
    answers: list[dict[str, Any]] = []
    for query in queries:
        feasible: np.ndarray | None = None
        for binding in query["fixed"]:
            flags = universe.column(binding["ref"]) == int(binding["value"])
            feasible = flags if feasible is None else (feasible & flags)
        if feasible is None:
            feasible = np.ones(universe.size, dtype=bool)
        for flags in active_flags:
            if not feasible.any():
                break
            feasible &= flags
        if not feasible.any():
            answers.append({"count": 0, "tokens": [], "witness": None})
            continue
        values = np.unique(universe.column(query["target"])[feasible])
        answers.append(
            {
                "count": int(feasible.sum()),
                "tokens": prefix_tokens(values, query["prefix"]),
                "witness": int(feasible.argmax()),
            }
        )
    return answers


def compile_job(job: dict[str, Any]) -> dict[str, Any]:
    """Compile one protocol job into rules, active theory and query answers."""
    schema = WindowSchema(job)
    universe = WindowUniverse(schema)
    miner = ClauseMiner(schema, universe, job["width"])
    rules = miner.rules()
    active = active_theory(rules, job["approved"])
    answers = decode_queries(schema, universe, miner.universe_flags, active, job["queries"])
    return {"rules": rules, "active": active, "answers": answers}
