"""Independent brute-force reference implementation of PROTOCOL.md."""
import itertools, json, operator

OPS = {'eq': operator.eq, 'ne': operator.ne, 'lt': operator.lt, 'le': operator.le,
       'gt': operator.gt, 'ge': operator.ge}


def bf_compile_job(job):
    fields = job['fields']
    names = [f['name'] for f in fields]
    idx = {n: i for i, n in enumerate(names)}
    doms = [list(f['domain']) for f in fields]
    K = job['slots']
    nf = len(fields)
    cells = K * nf
    cell_field = [i for _ in range(K) for i in range(nf)]
    dom_lists = [doms[cf] for cf in cell_field]
    universe = list(itertools.product(*dom_lists))
    U = len(universe)

    def cpos(ref):
        return ref[0] * nf + idx[ref[1]]

    def tval(term, w):
        if 'const' in term:
            return term['const']
        if 'sum' in term:
            return sum(w[cpos(r)] for r in term['sum'])
        if 'scale' in term:
            return term['scale'] * w[cpos(term['ref'])]
        return w[cpos(term['ref'])]

    def ev(p, w):
        if p['kind'] == 'cmp':
            return OPS[p['op']](tval(p['left'], w), tval(p['right'], w))
        fi = idx[p['field']]
        vals = [w[slot * nf + fi] for slot in range(K)]
        res = [OPS[p['op']](v, p['value']) for v in vals]
        return any(res) if p['kind'] == 'any' else all(res)

    preds = job['predicates']
    train = [tuple(itertools.chain.from_iterable(w)) for w in job['train']]
    width = job['width']

    def clause_true(clause, w):
        return any(ev(preds[i], w) for i in clause)

    rules = []
    for length in range(1, width + 1):
        for clause in itertools.combinations(range(len(preds)), length):
            if not all(clause_true(clause, w) for w in train):
                continue
            minimal = True
            for i in range(length):
                rest = clause[:i] + clause[i + 1:]
                if rest and all(clause_true(rest, w) for w in train):
                    minimal = False
                    break
                if not rest and train:
                    # empty clause is false everywhere -> removal breaks coverage
                    pass
            if not minimal:
                continue
            ce = None
            for u, w in enumerate(universe):
                if not clause_true(clause, w):
                    ce = u
                    break
            if ce is None:
                continue
            witnesses = []
            for i in range(length):
                wit = None
                for r, w in enumerate(train):
                    if ev(preds[clause[i]], w) and not any(
                            ev(preds[clause[j]], w) for j in range(length) if j != i):
                        wit = r
                        break
                witnesses.append(wit)
            rules.append({'clause': list(clause), 'witnesses': witnesses, 'counterexample': ce})
    rules.sort(key=lambda r: (len(r['clause']), r['clause']))

    approved = {tuple(c) for c in job['approved']}
    active = [r['clause'] for r in rules if tuple(r['clause']) in approved]

    answers = []
    for q in job['queries']:
        target_pos = cpos(q['target'])
        prefix = q['prefix']
        fixed = {cpos(b['ref']): b['value'] for b in q['fixed']}
        count = 0
        witness = None
        chars = set()
        end = False
        for u, w in enumerate(universe):
            if any(w[p] != v for p, v in fixed.items()):
                continue
            if not all(clause_true(c, w) for c in active):
                continue
            spelling = str(w[target_pos])
            if not spelling.startswith(prefix):
                continue
            count += 1
            if witness is None:
                witness = u
            if spelling == prefix:
                end = True
            elif len(spelling) > len(prefix):
                chars.add(spelling[len(prefix)])
        tokens = [d for d in '0123456789' if d in chars]
        if end:
            tokens.append('END')
        answers.append({'count': count, 'tokens': tokens,
                        'witness': witness if witness is not None else None})
    return {'rules': rules, 'active': active, 'answers': answers}
