                        others |= train_sets[j]
                candidates = train_sets[clause[i]] - others
                witnesses.append(min(candidates) if candidates else None)
            rules.append({'clause': list(clause), 'witnesses': witnesses,
                          'counterexample': min(missing)})
    rules.sort(key=lambda r: (len(r['clause']), r['clause']))

    approved = {tuple(c) for c in job['approved']}
    active = [r['clause'] for r in rules if tuple(r['clause']) in approved]
    active_sets = []
    for clause in active:
        s = set()
        for i in clause:
            s |= uni_sets[i]
        active_sets.append(s)

    answers = []
    for q in job['queries']:
        target_pos = cpos(q['target'])
        prefix = q['prefix']
        fixed = {cpos(b['ref']): b['value'] for b in q['fixed']}
        count = 0
        witness = None
        chars = set()
