class WindowUniverse:
    """Every window over the declared domains in mixed-radix protocol order.

    Index 0 is the all-smallest window; the last cell (highest slot, last field)
    varies fastest.  Domain positions, not numeric gaps, are the digits.
    """

    def __init__(self, schema: WindowSchema):
        self.schema = schema
        self.cells = schema.slots * schema.nf
        self.cell_field = [
            field_index for _ in range(schema.slots) for field_index in range(schema.nf)
        ]
        self.radices = [len(schema.field_domains[field_index]) for field_index in self.cell_field]
        size = 1
        for radix in self.radices:
            size *= radix
        self.size = int(size)
        self.multipliers = [0] * self.cells
        weight = 1
        for cell in range(self.cells - 1, -1, -1):
            self.multipliers[cell] = weight
            weight *= self.radices[cell]
        self.domain_arrays = [
            np.asarray(domain, dtype=np.int64) for domain in schema.field_domains
        ]
        self.matrix = self._enumerate()

    def _enumerate(self) -> np.ndarray:
        positions = np.arange(self.size, dtype=np.int64)
        matrix = np.empty((self.size, self.cells), dtype=np.int64)
        for cell in range(self.cells):
            values = self.domain_arrays[self.cell_field[cell]]
            matrix[:, cell] = values[(positions // self.multipliers[cell]) % self.radices[cell]]
        return matrix

    def train_matrix(self, train: list[list[list[int]]]) -> np.ndarray:
        rows = [list(itertools.chain.from_iterable(window)) for window in train]
        if not rows:
            return np.zeros((0, self.cells), dtype=np.int64)
        matrix = np.asarray(rows, dtype=np.int64)
        return matrix.reshape(len(rows), self.cells)

    def index_of(self, window: list[list[int]]) -> int:
        """Universe index of one concrete window (used by diagnostics/tests)."""
        flat = list(itertools.chain.from_iterable(window))
        index = 0
        for cell, value in enumerate(flat):
            domain = self.schema.field_domains[self.cell_field[cell]]
            index += domain.index(value) * self.multipliers[cell]
        return index

    def column(self, ref: list[Any]) -> np.ndarray:
        return self.matrix[:, self.schema.position(ref)]


def prefix_match_mask(values: np.ndarray, prefix: str) -> np.ndarray:
    """Vectorised ``str(value).startswith(prefix)`` over canonical spellings.

    Canonical decimal spellings carry no sign and no leading zero, so a value of
    ``digits`` decimal digits starts with ``prefix`` exactly when the leading
    ``len(prefix)`` digits equal ``int(prefix)``.  Grouping values by digit
    length keeps this a handful of vector comparisons instead of string work.
    """
    if values.size == 0:
        return np.zeros(0, dtype=bool)
    if not prefix:
        return np.ones(values.size, dtype=bool)
    target = int(prefix)
    length = len(prefix)
    match = np.zeros(values.size, dtype=bool)
    for digits in range(1, 8):
        if digits < length:
            continue
        low = 0 if digits == 1 else 10 ** (digits - 1)
        high = 9 if digits == 1 else 10 ** digits - 1
        selected = (values >= low) & (values <= high)
        match |= selected & ((values // 10 ** (digits - length)) == target)
    return match


def _spelling_equals(values: np.ndarray, prefix: str) -> bool:
    """Is ``prefix`` exactly the canonical spelling of one of ``values``?"""
    if not prefix:
        return False
    value = int(prefix)
    if str(value) != prefix:
        return False
    return bool((values == value).any())


def prefix_tokens(values: np.ndarray, prefix: str) -> list[str]:
    """Next tokens of ``values`` after ``prefix``, as ``"0".."9"`` then ``"END"``.

    Every value in ``values`` already starts with ``prefix``, so a value with
    more digits than ``prefix`` contributes the digit at that position and a
    value with exactly ``len(prefix)`` digits contributes ``"END"``.
    """
    present = np.zeros(10, dtype=bool)
    length = len(prefix)
    if length and _spelling_equals(values, prefix):
        present_end = True
    else:
        present_end = False
    for digits in range(max(1, length), 8):
        low = 0 if digits == 1 else 10 ** (digits - 1)
        high = 9 if digits == 1 else 10 ** digits - 1
        if digits == length:
            continue
        selected = (values >= low) & (values <= high)
        if not selected.any():
            continue
        shift = 10 ** (digits - length - 1)
        present[(values[selected] // shift) % 10] = True
    tokens = [DIGITS[digit] for digit in range(10) if present[digit]]
    if present_end:
        tokens.append("END")
    return tokens


